                g[y][c] = 1

    # With multiple marks, each mark's 3x3 frame is echoed in the other
    # mark's row band. The central 2 remains a separator.
    if len(centers) >= 2:
        for i, (r, c) in enumerate(centers):
            for rr, cc in centers[:i] + centers[i+1:]:
                for dr in (-1, 0, 1):
